#!/usr/bin/env node
// Generator for VEC-OBS-5's composed tutor bench set (SRV-OBS FR-OBS-22, phase 2 design review round 1, B5):
// spikes/embeddings-local/questions-v2.yaml with v03 replaced by t01 of spec/fixtures/SRV-TUTOR/bench-fixed.yaml, in
// v03's place (VEC-TUTOR-7's `replace: {v03: t01}`), written to spec/fixtures/SRV-OBS/bench-tutor-v2.yaml with the
// two sources' sha256s in its header. The composed file has ONE sha256, which VEC-OBS-5 pins. Each record keeps only
// the keys the dataset uses: id, chapter (an integer, 1..23), gold_pages (integers), question.
// Run: node spec/fixtures/SRV-OBS/compose-bench.mjs [--check] (needs tools/node_modules: npm ci --prefix tools).
// --check exits 1 when the committed file differs from what the sources give.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '../../..');
const require = createRequire(join(root, 'tools/package.json'));
const { parse } = require('yaml');

const V2 = 'spikes/embeddings-local/questions-v2.yaml';
const FIXED = 'spec/fixtures/SRV-TUTOR/bench-fixed.yaml';
const OUT = 'spec/fixtures/SRV-OBS/bench-tutor-v2.yaml';
const sha = (bytes) => createHash('sha256').update(bytes).digest('hex');
const read = (p) => readFileSync(join(root, p));

const v2 = parse(read(V2).toString('utf8')).questions;
const fixed = Object.fromEntries(parse(read(FIXED).toString('utf8')).questions.map((q) => [q.id, q]));
const records = v2.map((q) => (q.id === 'v03' ? fixed.t01 : q));
if (!fixed.t01 || records.length !== 40) throw new Error('expected 40 records with t01 in place of v03');
const line = (q) => {
  if (!Number.isInteger(q.chapter) || q.chapter < 1 || q.chapter > 23) throw new Error(`chapter of ${q.id}`);
  if (!q.gold_pages.every(Number.isInteger)) throw new Error(`gold_pages of ${q.id}`);
  return `  - { id: ${q.id}, chapter: ${q.chapter}, gold_pages: [${q.gold_pages.join(', ')}], question: ${JSON.stringify(q.question)} }`;
};
const text = [
  '# GENERATED by spec/fixtures/SRV-OBS/compose-bench.mjs: do not edit. VEC-OBS-5 `bench_sets.tutor-bench-v2`.',
  `# Sources: ${V2} (sha256 ${sha(read(V2))}) with v03 replaced by t01 of ${FIXED} (sha256 ${sha(read(FIXED))}).`,
  '# The questions are the agent\'s own committed wording (each source\'s header); the verbatim book check is',
  '# spikes/obs-stack/check_bench_quotes.py (FR-OBS-22).',
  'questions:',
  ...records.map(line),
  '',
].join('\n');
if (process.argv.includes('--check')) {
  const now = read(OUT).toString('utf8');
  if (now !== text) {
    console.error(`${OUT} is out of date: run node ${OUT.replace('bench-tutor-v2.yaml', 'compose-bench.mjs')}`);
    process.exit(1);
  }
} else {
  writeFileSync(join(root, OUT), text);
}
console.log(`${OUT} sha256 ${sha(Buffer.from(text, 'utf8'))} records ${records.length}`);
